/*
 * The on-device models this build offers: the pinned WebLLM models (webllm-models.json, generated by
 * web/scripts/pin-local-models.ts) and Chrome's built-in model, with their capabilities and the URLs their files are
 * read from. Small and pure: the session loads it to resolve local models; llm-models' ranking lives in models.ts.
 */
import type { Capabilities, ProviderKind } from '../../contracts/ai.ts'
import type { PinnedModel } from '../../contracts/local.ts'
import pins from './webllm-models.json'

export const WEBLLM_VERSION: string = pins.webllm

/** Every pinned WebLLM model, smallest first. */
export const WEBLLM_MODELS: readonly PinnedModel[] = pins.models

const byId = new Map(WEBLLM_MODELS.map((m) => [m.id, m]))

export function pinnedModel(id: string): PinnedModel | undefined {
  return byId.get(id)
}

/** The id Chrome's built-in model (Gemini Nano through the Prompt API) is listed under. */
export const CHROME_AI_MODEL = 'gemini-nano'

/** Whether a provider kind runs in this browser rather than over the network. */
export function isOnDevice(kind: ProviderKind): boolean {
  return kind === 'webllm' || kind === 'chrome-ai'
}

const HF = 'https://huggingface.co'

/** Where a model's files are read: its repository at its pinned commit, as WebLLM spells a model URL. */
export function modelBaseUrl(model: Pick<PinnedModel, 'repo' | 'commit'>): string {
  return `${HF}/${model.repo}/resolve/${model.commit}/`
}

/**
 * Every URL a model may fetch, with its SHA-256 (hex): each file of `files` under the model's base URL, and its
 * library. Nothing else is admitted.
 */
export function pinnedUrls(model: PinnedModel, files: Readonly<Record<string, string>>): Map<string, string> {
  const base = modelBaseUrl(model)
  const out = new Map<string, string>()
  for (const [path, sha256] of Object.entries(files)) out.set(new URL(path, base).href, sha256)
  out.set(model.lib.url, model.lib.sha256)
  return out
}

/** The name a local model is shown under. */
export function localModelName(kind: ProviderKind, modelId: string): string | null {
  if (kind === 'webllm') return pinnedModel(modelId)?.name ?? null
  if (kind === 'chrome-ai' && modelId === CHROME_AI_MODEL) return 'Gemini Nano'
  return null
}

/** Gemini Nano's input window in Chrome (the Prompt API's `inputQuota`). */
const CHROME_AI_CONTEXT = 6144

const BASE: Omit<Capabilities, 'tools' | 'reasoning' | 'thinkingDisplay' | 'contextWindow' | 'maxOutput'> = {
  vision: false,
  pdf: false,
  effort: { levels: [], default: null },
  sampling: [],
  prefill: false,
  forcedToolChoice: false,
  webSearch: null,
  midConversationSystem: false,
  toolChanges: false,
  refusalFallback: null,
  cost: { input: 0, output: 0 },
}

/**
 * What a local model accepts: text only, no effort scale, free. Tools only where WebLLM supports function calling
 * (the Hermes builds that say so); reasoning for the models that think in `<think>` blocks, shown raw. A model the
 * build does not pin gets the most conservative set and a small window.
 */
export function localCapabilities(kind: ProviderKind, modelId: string): Capabilities {
  if (kind === 'webllm') {
    const model = pinnedModel(modelId)
    const contextWindow = model?.contextWindow ?? 2048
    return {
      ...BASE,
      sampling: ['temperature', 'topP', 'presencePenalty', 'frequencyPenalty', 'seed'],
      tools: model?.tools ?? false,
      reasoning: model?.reasoning ?? false,
      thinkingDisplay: model?.reasoning === true ? 'raw' : null,
      contextWindow,
      maxOutput: Math.floor(contextWindow / 2),
    }
  }
  return {
    ...BASE,
    tools: false,
    reasoning: false,
    thinkingDisplay: null,
    contextWindow: CHROME_AI_CONTEXT,
    maxOutput: 2048,
  }
}
